import json
files=['scratch/t01/inbox/t01f/output.json','scratch/t01/inbox/t01g/output.json','scratch/t18/out/bridge.json','scratch/t18/out/REPORT.md','scratch/t18/out/fields_club.json','scratch/t18/out/fields_club.part001.json','scratch/t18/out/fields_nati.json','scratch/t18/out/fields_nati.part001.json','scratch/t05/reader_widths.json','scratch/t05/COVERAGE.json','scratch/t12/out/codes_full.json','evidence/fm24/reports/editor_schema/master.json']
for p in files:
 print('\n###',p)
 if p.endswith('.md'):
  print(open(p,encoding='utf8').read()[:8000]); continue
 try:d=json.load(open(p,encoding='utf8'))
 except Exception as e: print(e); continue
 if p.endswith('output.json') and 't01f' in p:
  print('cursor:',json.dumps(d['row_codec']['cursor_layout'],ensure_ascii=False,indent=2)[:11000])
 elif p.endswith('output.json'):
  print('cursor:',json.dumps(d['row_codec']['cursor_layout'],ensure_ascii=False,indent=2)[:14000])
 elif p.endswith('bridge.json'):
  print('keys',d.keys()); print(json.dumps(d,ensure_ascii=False,indent=2)[:5000])
 elif 'fields_' in p:
  print(json.dumps(d,ensure_ascii=False,indent=2)[:4000])
 elif 'reader_widths' in p:
  for r in d['results']:
   if r.get('type_id') in (3,10,25): print(json.dumps(r,ensure_ascii=False,indent=2)[:12000])
 elif 'COVERAGE' in p:
  print('table club/nati:',*[x for x in d['tables'] if x.get('entity') in ('club','nati','nation')],sep='\n')
 elif 'codes_full' in p:
  print(type(d), str(d)[:5000])
 else:
  print('keys',d.keys()); print('entity maybe',str(d.get('entities',{}).get('club'))[:2000])
